    int32_t nWorldOffset;
    int nBorderShift;
    uint32_t eBorderType;
    eBorderType = Path::DRAW_GetTypeOfBorder();
    if (eBorderType == 3) {
      return;
    }

    int32_t nCoord;
    nCoord = 0;
    D2UnitStrc* pMercUnit;
    pMercUnit = UNIT::Player::GetPlayerUnit_UI();
    nCoord = GAME::RosterPets::GetRosterPetGUID(pMercUnit, 7, nCoord);
    if (nCoord == -1) {
      return;
    }

    D2SeedStrc* pSeed;
    pSeed = GAME::RosterPets::GetSeed(nCoord);
    if (pSeed[1].nSeedLow != 1) {
      return;
    }

    pMercUnit = UNIT::Player::UNITS_FindClientSideUnit(nCoord, UNIT_MONSTER);
    if (!pMercUnit) {
      return;
    }

    eBorderType = D2gfx::D2GFX::D2GFX_IsPerspectiveActive();
    if (!eBorderType) {
      nCoord = D2Common::Units::GetTargetX(pMercUnit);
      nWorldOffset = Path::DRAW_GetWorldOffsetX();
      nHealthBarScreenX = nCoord - nWorldOffset;
      nCoord = D2Common::Units::GetTargetY(pMercUnit);
      nWorldOffset = Path::DRAW_GetWorldOffsetY();
      gnMercenaryHealthBarScreenY = nCoord - nWorldOffset;
      UI_ShowMonsterNameBar(1, pMercUnit);
      return;
    }

    nCoord = D2Common::Units::GetPrecisionX(pMercUnit);
    nWorldOffset = D2Common::Units::GetPrecisionY(pMercUnit);
    eBorderType = D2gfx::D2GFX::D2GFX_IsInPerspectiveBounds(nCoord, nWorldOffset);
    if (!eBorderType) {
      return;
    }

    D2gfx::D2GFX::D2GFX_AdjustPerspectivePosition(nCoord, nWorldOffset, 0, &__frame0.nScreenX, &__frame0.nScreenY);
