// Handles key input and dismisses UI panels based on gUIFlagDismissModeTable. Scans all active UI flags and applies dismiss action (0=ignore, 1=close, 2=block, 4=close NPC). Special handling for quest log (index 5) and quest resurrect (index 9) with tick throttle. Returns 0 if action was blocked or consumed, 1 if input should propagate.
uint32_t UI_HandleKeyInputAndDismiss(int32_t nKeyAction, int32_t nUIFlagToCheck) {
    DWORD dwTickCount;
    D2UnitStrc* pPlayerUnit_lcl;
    uint32_t bTextScrolling;
    BOOL bGotInteractGuid;
    int32_t nInteractGuid;
    int32_t nLine;
    if (gnUIFlagCount != 0x26) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), nLine);
      exit(-1);
    }

    eD2UIvars eCurrentUI;
    eCurrentUI = UI_GAME;
    if (!(!nKeyAction || nKeyAction == 2 && !(&GFX_bShowUIFlag.Game)[nUIFlagToCheck])) {
      return 1;
    }
    if (nUIFlagToCheck == 5 || nUIFlagToCheck == 9) {
      int nDialogCounter;
      nDialogCounter = Dialog::GetDialogCounter();
      if (nDialogCounter && nUIFlagToCheck == 5 && !GFX_bShowUIFlag.MessageLog) {
        return 0;
      }

      dwTickCount = GetTickCount();
      if (dwTickCount < gdwQuestResurrectDismissThrottle) {
        return 0;
      }
      if (nUIFlagToCheck == 9) {
        pPlayerUnit_lcl = UNIT::Player::GetPlayerUnit_UI();
        if (!pPlayerUnit_lcl) {
          return 0;
        }
        if (pPlayerUnit_lcl->eUnitType == UNIT_PLAYER && pPlayerUnit_lcl->eAnimMode.ePlayerMode == eD2PlayerAnimMode_ns::Dead) {
          UNIT::CUnit::IsAttackable(pPlayerUnit_lcl);
          GAME::Msg::NET_D2GS_CLIENT_Send_CMD(0x41);
          bTextScrolling = ClientModeInGame::CLIENTMODE_GetIngameUIFlags();
          if (!bTextScrolling) {
            return 0;
          }

          GAME::Msg::NET_D2GS_CLIENT_Send_0x69();
          ServerLoadingComplete = 0;
          D2GS_Connected = 0;
          ClientModeInGame::CLIENTMODE_ClearIngameUIFlag();
          ClientModeInGame::D2CLIENT_SetExitVar1(0);
          GAME::Game::D2CLIENT_SetExitVar3ToTrue();
          return 0;
        }
      }
    }

    bTextScrolling = Text::TEXT_IsScrollingTextActive();
    if (bTextScrolling && nUIFlagToCheck != 10 && nUIFlagToCheck != 0x13 && nUIFlagToCheck != 0x11 && nUIFlagToCheck != 6 && nUIFlagToCheck != 7) {
      return 0;
    }
    if (0 >= gnUIFlagCount) {
      return 1;
    }

    do {
      if ((&GFX_bShowUIFlag.Game)[eCurrentUI] == 1) {
        if (false) {
          default_case:
          if (nUIFlagToCheck) {
            return 0;
          }
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x13e6);
          exit(-1);
        }

        switch (*(uint32_t*)(gUIFlagDismissModeTable[eCurrentUI]->aHeader + nUIFlagToCheck * 4)) {
          case 0:
            break;
          case 1:
            Draw::SetUIFlag(eCurrentUI, UI_RESET, 0);
          break;
          case 2:
            return 0;
          default:
            goto default_case;
          case 4:
            bGotInteractGuid = npcmenu::GetInteractedUnitGuid(&nInteractGuid);
          if (bGotInteractGuid) {
            npcmenu::NPCMENU_CloseNpcInteraction(nInteractGuid);
          }
        }
      }

      eCurrentUI += UI_INVENTORY;
    } while ((int)eCurrentUI < gnUIFlagCount);

    return 1;
}

