void __stdcall UI_CloseCurrentDialog() {
    if (gbKeyConfigModeActiveInDialog) {
      CmdTbl::CMD_ToggleKeyConfigMode(1, 1);
      gbKeyConfigModeActiveInDialog = 0;
    }
    if (gpDialogDefaultActionCallback) {
      gnGoldDialogTransactionMode = gpDialogDefaultActionCallback->pVtable->GetValue(gpDialogDefaultActionCallback);
    }
    if (Dialog::gpDialog) {
      Dialog::FreeDialogStrc();
      Dialog::gpDialog = 0;
    }
    if (gpCurrentDialog) {
      gpCurrentDialog->pVtable->ScalarDeletingDestructor(gpCurrentDialog, 1);
      gpCurrentDialog = 0;
    }
    if (gpDialogDefaultActionCallback) {
      gpDialogDefaultActionCallback->pVtable->ScalarDeletingDestructor(gpDialogDefaultActionCallback, 1);
      gpDialogDefaultActionCallback = 0;
    }
    if (gpUiGoldTransactionDialog) {
      gpUiGoldTransactionDialog->pVtable->ScalarDeletingDestructor(gpUiGoldTransactionDialog, 1);
      gpUiGoldTransactionDialog = 0;
    }
    if (gpUiGoldDialogCancelButton) {
      gpUiGoldDialogCancelButton->pVtable->ScalarDeletingDestructor(gpUiGoldDialogCancelButton, 1);
      gpUiGoldDialogCancelButton = 0;
    }
    if (gnGoldDialogTransactionType) {
      if (!(0 < gnGoldDialogTransactionType && gnGoldDialogTransactionType < 5)) {
        return;
      }

      Inv::INV_StashOpened();
      return;
    }

    UI_ClearGoldStashMode();
}

