int __stdcall UI_GoldDialogScrollCallback() {
    eD2UnitStat eUnitStat;
    int nScrollDirection = gpCurrentDialog->pVtable->GetValue(gpCurrentDialog);
    uint32_t uScrollDelta = gpCurrentDialog->pVtable->GetRepeatDelta(gpCurrentDialog, 0);
    if (gpDialogDefaultActionCallback) {
      gnGoldDialogTransactionMode = gpDialogDefaultActionCallback->pVtable->GetValue(gpDialogDefaultActionCallback);
    }

    uint32_t uGoldAmount = gnGoldDialogTransactionMode;
    uint16_t nLayer = 0;
    if (gnGoldDialogTransactionType == 4) {
      eUnitStat = UNITSTAT_goldbank;
    } else {
      eUnitStat = UNITSTAT_gold;
    }

    D2UnitStrc* pUnit = UNIT::Player::GetPlayerUnit_UI();
    uint32_t uMaxGoldAvailable = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, eUnitStat, nLayer);
    if (nScrollDirection == 1) {
      uGoldAmount += uScrollDelta;
      if (uMaxGoldAvailable < uGoldAmount) {
        uGoldAmount = uMaxGoldAvailable;
      }
    } else if (nScrollDirection == 2) {
      if (uGoldAmount < uScrollDelta) {
        uGoldAmount = 0;
      } else if (uGoldAmount) {
        uGoldAmount -= uScrollDelta;
      }
    }

    gnGoldDialogTransactionMode = uGoldAmount;
    if (!gpDialogDefaultActionCallback) {
      return 0;
    }

    gpDialogDefaultActionCallback->pVtable->SetNumber(gpDialogDefaultActionCallback, uGoldAmount);
    return 0;
}

// Activate callback of the gold dialog's confirm button: closes the dialog and sends the gold transaction for the entered amount. No arguments and a plain RET, so it fits the cdecl fpButtonOnActivate slot.
int UI_GoldDialogConfirmCallback() {
    D2UnitStrc* pPlayer;
    int nPlayerGUID;
    int16_t nButtonId;
    UI_CloseCurrentDialog();
    if (!gnGoldDialogTransactionMode) {
      if (gnGoldDialogTransactionType != 2) {
        return 1;
      }

      TRADE_SendGoldToPartner(0);
      return 1;
    }

    switch (gnGoldDialogTransactionType) {
      case 0:

      case 1:
        pPlayer = UNIT::Player::GetPlayerUnit_UI();
      if (!pPlayer) {
        nPlayerGUID = -1;
      } else {
        nPlayerGUID = pPlayer->nUnitGUID;
      }

      GAME::Msg::NET_D2GS_CLIENT_Send_INT_INT(0x50, nPlayerGUID, gnGoldDialogTransactionMode);
      return 1;
      case 2:
        TRADE_SendGoldToPartner(gnGoldDialogTransactionMode);
      goto play_confirm_sound;
      case 3:
        nButtonId = 0x14;
      break;
      case 4:
        nButtonId = 0x13;
      break;
      default:
        return 1;
    }

    GAME::Msg::NET_D2GS_CLIENT_Send_SHORT_SHORT_SHORT(0x4f, nButtonId, (int16_t)(gnGoldDialogTransactionMode >> 0x10), (int16_t)gnGoldDialogTransactionMode);
    play_confirm_sound:
    Sound::SOUND_PlaySound(SOUND_ITEM_METALSHIELD, nullptr, 0, 0, 0);
    return 1;
}

int UI_ButtonCallback_CloseDialog() {
    UI_CloseCurrentDialog();
    return 1;
}

