void __stdcall INPUT_ConfigMouseButtonHandler(D2UIMouseMsgStrc * pMsg) {
    uint16_t nKeyCode;
    BOOL bExitFlag;
    bExitFlag = GAME::Game::GAMEDATA_GetExitFlag3();
    if (bExitFlag) {
      pMsg->bHandled = 0;
      return;
    }

    short int nMouseButton;
    nMouseButton = *(short int*)((uintptr_t)&pMsg->nWParam + 2);
    if (nMouseButton == 1) {
      nKeyCode = 0x101;
    } else {
      if (nMouseButton != 2) {
        goto consume_click;
      }

      nKeyCode = 0x102;
    }

    UI_ConfigSetKeyBinding(nKeyCode);
    consume_click:
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
}

void __stdcall INPUT_ConfigMouseWheelScroll(D2UIMouseMsgStrc * pMsg) {
    BOOL bExitFlag = GAME::Game::GAMEDATA_GetExitFlag3();
    D2UIMouseMsgStrc* pUnderMouseOrig = pMsg;
    if (bExitFlag) {
      pMsg->bHandled = 0;
      return;
    }

    int nScrollTicks = (int)*(short int*)((uintptr_t)&pMsg->nWParam + 2);
    int iVar1 = nScrollTicks >> 0x1f;
    nScrollTicks = nScrollTicks / 0x78 + iVar1;
    if (nScrollTicks != iVar1) {
      pMsg = 0;
      bExitFlag = CmdTbl::CMD_SetKeyBinding(gpStatDescriptorTable[g_ControlConfigUIState].nCmdIndex, nConfigControlSelected, (nScrollTicks - iVar1 < 0) + 0x103, (uint16_t*)&pMsg);
      if (!bExitFlag) {
        if ((short int)(uintptr_t)pMsg) {
          *(uint16_t*)(char*)&gnUICtrlConfigPendingKeyStrId = (short int)(uintptr_t)pMsg;
          gdwUICtrlConfigKeyBindTimestamp = GetTickCount();
        }
      } else {
        UI_ConfigKeyBindModeDisable(1);
      }
    }

    pUnderMouseOrig->bHandled = 1;
    pUnderMouseOrig->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pUnderMouseOrig);
}

