BOOL NPCSHOP_GetActiveTabIndex(int32_t nMouseY, int32_t nMouseX) {
    BOOL bHandled = 0;
    int nTabIdx = 0;
    if (0 < nCashDisplayItemCount) {
      do {
        if (gaNpcCashTabs[nTabIdx].bVisible && gaNpcCashTabs[nTabIdx].nHitBoxX1 <= nMouseX && nMouseX <= gaNpcCashTabs[nTabIdx].nHitBoxX2 && gaNpcCashTabs[nTabIdx].nHitBoxY1 <= nMouseY && nMouseY <= gaNpcCashTabs[nTabIdx].nHitBoxY2) {
          Sound::SOUND_PlaySound(SOUND_CURSOR_PASS, nullptr, 0, 0, 0);
          if (!nTabIdx) {
            TEXT_HandleMouseMove();
          } else {
            NPCSHOP_IsRepairTabActive();
          }

          bHandled = 1;
        }

        nTabIdx++;
      } while (nTabIdx < nCashDisplayItemCount);
    }
    if (0 >= nCashDisplayItemCount) {
      return bHandled;
    }

    uint8_t* pHitTestState = &gaNpcCashTabs[0].nHitTestState;
    nTabIdx = nCashDisplayItemCount;
    do {
      pHitTestState[1] = 0;
      *pHitTestState = 0;
      pHitTestState += 0x28;
      nTabIdx--;
    } while (nTabIdx);

    return bHandled;
}

void __stdcall INPUT_GambleRepairClick(D2UIMouseMsgStrc * pMsg) {
    BOOL bTabHandled;
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
    uint32_t nMouseX = (uint32_t)pMsg->uLParam.sMousePos.nMouseX;
    uint32_t nMouseY = (uint32_t)pMsg->uLParam.sMousePos.nMouseY;
    if (gnPlayerCashDisplay == 2) {
      bTabHandled = NPCSHOP_GetActiveTabIndex(nMouseY, nMouseX);
      if (!bTabHandled) {
        bTabHandled = Inv::INV_HandleInventoryLeftDown(pMsg);
        if (bTabHandled) {
          NPCSHOP_IsRepairTabActive();
          return;
        }
      }
    } else {
      bTabHandled = Inv::INV_HandleInventoryLeftClick(pMsg);
      if (!bTabHandled) {
        NPCSHOP_GetActiveTabIndex(nMouseY, nMouseX);
      }
    }
}

